 if('[],'.includes(c)){i++;column++} else if(c==='\"'){i++;column++;while(i<source.length&&source[i]"'!=='"'\"'&&source[i]"'!=='"'\\n'){i++;column++} if(source[i]==='\"'){i++;column++}} else {while(i<source.length&&"'!/['"\\s\\[\\],;]/.test(source[i])){i++;column++}}
