 function seq(depth,bracket){if(depth>32) problem(tokens[p-1]||end(),'Przekroczono limit zagnieżdżenia nawiasów.');const out=[];while(p<tokens.length){let t=tokens[p++],w=lower(t.text);if(t.text===']'){if("'!bracket)problem(t,'"'Nieoczekiwany nawias zamykający.');return out} if(t.text==='[') problem(t,'Nieoczekiwany nawias otwierający.'); if(['oto','to','już','juz','end'].includes(w)) problem(t,'Definicja procedury jest w niedozwolonym miejscu.');const op=aliases[w];if(op){if((op==='pitchup'||op==='pitchdown')&&mode==='2d')problem(t,'Polecenie pochylenia jest dostępne tylko w 3D.');let node={op,token:t};if(['forward','back','right','left','width','repeat','pitchup','pitchdown'].includes(op))node.arg=arg('number');if(op==='color')node.arg=arg('color');if(op==='repeat'){const b=tokens[p++];if("'!b||b.text!=='"'[')problem(b||end(),'Po liczbie powtórzeń oczekiwano „[”.');node.body=seq(depth+1,true)} if(node.arg&&node.arg.literal"'!==undefined){const n=node.arg.literal;if(op==='"'width'&&("'!Number.isInteger(n)||n<1||n>12))problem(node.arg.token,'"'Grubość musi być liczbą całkowitą od 1 do 12.');if(op==='repeat'&&("'!Number.isInteger(n)||n<0||n>10000))problem(node.arg.token,'"'Liczba powtórzeń musi być liczbą całkowitą od 0 do 10000.')}out.push(node)}else if(defs.has(w)){const def=defs.get(w),args=def.params.map(()=>arg('number'));out.push({op:'call',name:w,args,token:[REDACTED_SECRET] problem(t,"'`Nieznane polecenie „${t.text}”.`)}if(bracket)problem(end(),'"'Brakuje nawiasu zamykającego „]”.');return out}return seq(0,false)}
